import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "../lib/db";

const exec = promisify(execFile);

const CHAIN = process.env.NXEON_NAT_CHAIN ?? "NXEON_FWD";

async function iptables(args: string[]) {
  await exec("iptables", args);
}

async function ensureChain() {
  try {
    await iptables(["-t", "nat", "-N", CHAIN]);
  } catch {
    /* chain exists */
  }
  // Ensure PREROUTING jumps to our chain exactly once
  try {
    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", CHAIN]);
  } catch {
    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", CHAIN]);
  }
}

/** Rebuild the entire NXEON_FWD chain from the database. Idempotent. */
export async function syncPortForwards() {
  await ensureChain();
  await iptables(["-t", "nat", "-F", CHAIN]);

  const servers = await db.server.findMany({
    where: {
      ipAddress: { not: null },
      sshPort: { not: null },
      status: { notIn: ["SUSPENDED", "DELETING"] },
    },
    include: { portForwards: true },
  });

  for (const s of servers) {
    await iptables([
      "-t", "nat", "-A", CHAIN,
      "-p", "tcp", "--dport", String(s.sshPort),
      "-j", "DNAT", "--to-destination", `${s.ipAddress}:22`,
    ]);
    for (const f of s.portForwards) {
      await iptables([
        "-t", "nat", "-A", CHAIN,
        "-p", f.protocol, "--dport", String(f.publicPort),
        "-j", "DNAT", "--to-destination", `${s.ipAddress}:${f.guestPort}`,
      ]);
    }
  }
}

import { db } from "../lib/db";
import { pve, node, waitForTask, nextVmid, pveFor, vmStatus } from "../lib/proxmox";
import { writeFile } from "node:fs/promises";
import { allocateIp, allocateSshPort, gatewayIp } from "../lib/ipam";
import { syncPortForwards } from "./network";
import { billingSweep } from "./billing";
import { randomBytes } from "node:crypto";
import type { Job, Server } from "@prisma/client";

const POLL_MS = 3000;
const MAX_ATTEMPTS = 3;

function generatePassword(): string {
  // URL-safe, no ambiguous chars, 16 chars
  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
}

async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any }> {
  const server = await db.server.findUnique({
    where: { id: job.serverId! },
    include: { plan: true, osTemplate: true, node: true },
  });
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  return server as any;
}

/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
async function nodeFor(server: any) {
  const n =
    server.node ??
    (await db.node.findFirst({ where: { isPrimary: true } })) ??
    (await db.node.findFirst({ where: { enabled: true } }));
  if (!n) {
    // No Node rows yet — use the env-configured primary via the global client.
    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
  }
  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
}

/** YAML-safe indent of a multi-line script under a `content: |` block. */
function indentBlock(text: string, spaces: number): string {
  const pad = " ".repeat(spaces);
  return text.split("\n").map((l) => pad + l).join("\n");
}

/**
 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
 * plus any control-panel/app install script and selected add-ons. Long installs
 * run in the background so the VM reports ready promptly.
 */
function buildCloudInit(server: any): string {
  const addons = (server.addons ?? {}) as { malwareScanner?: boolean; dailyBackup?: boolean; docker?: boolean };
  const setup: string[] = [];
  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
  if (addons.malwareScanner)
    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);

  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
  return `#cloud-config
package_update: true
packages:
  - qemu-guest-agent
ssh_pwauth: true
disable_root: false
write_files:
  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
    permissions: "0644"
    content: |
      PermitRootLogin yes
      PasswordAuthentication yes
  - path: /root/nxeon-setup.sh
    permissions: "0755"
    content: |
${indentBlock(script, 6)}
runcmd:
  - systemctl enable --now qemu-guest-agent
  - systemctl restart ssh || systemctl restart sshd
  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
`;
}

const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";

async function provision(job: Job) {
  const server = await loadServer(job);
  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });

  const { conn, row: nodeRow } = await nodeFor(server);
  const storage = server.plan.storageTier === "hdd"
    ? nodeRow?.storageHdd ?? "vmdata-hdd"
    : nodeRow?.storageNvme ?? "vmdata";

  const vmid = server.vmid ?? (await conn.nextVmid());
  const ip = server.ipAddress ?? (await allocateIp());
  const sshPort = server.sshPort ?? (await allocateSshPort());
  const password = generatePassword();

  await db.server.update({
    where: { id: server.id },
    data: { vmid, ipAddress: ip, sshPort, rootPassword: password },
  });

  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
  const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
    newid: vmid,
    name: server.hostname,
    full: 1,
    storage,
  });
  await conn.waitForTask(cloneUpid, 600_000);

  // Per-server cloud-init snippet (base + panel/app install + add-ons)
  const snippet = buildCloudInit(server);
  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
    console.error("[worker] snippet write failed", e)
  );

  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
  const sshkeys = keys.length
    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
    : undefined;
  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, {
    cores: server.plan.cpuCores,
    memory: server.plan.ramMB,
    ciuser: "root",
    cipassword: password,
    sshkeys,
    ipconfig0: `ip=${ip}/24,gw=${gatewayIp()}`,
    nameserver: "1.1.1.1 8.8.8.8",
    onboot: 1,
    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
  });

  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
    disk: "scsi0",
    size: `${server.plan.diskGB}G`,
  });

  await syncPortForwards();

  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
  await conn.waitForTask(startUpid);

  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
  const isImage = server.osTemplate.category !== "PLAIN_OS";
  await notify(
    server.userId,
    `Server ${server.hostname} is ready`,
    isImage
      ? `${server.osTemplate.name} is installing in the background (a few minutes). SSH: ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`
      : `SSH: ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`,
    `/dashboard/servers/${server.id}`
  );
}

async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
  const server = await loadServer(job);
  const upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/${action}`, {});
  await waitForTask(upid);
  await db.server.update({
    where: { id: server.id },
    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
  });
}

async function destroyVm(vmid: number) {
  // Stop first (ignore failure if already stopped), then destroy
  try {
    const stopUpid = await pve.post(`/nodes/${node}/qemu/${vmid}/status/stop`, {});
    await waitForTask(stopUpid);
  } catch {
    /* already stopped or does not exist */
  }
  const delUpid = await pve.del(`/nodes/${node}/qemu/${vmid}`, {
    "destroy-unreferenced-disks": 1,
    purge: 1,
  });
  await waitForTask(delUpid, 600_000);
}

async function remove(job: Job) {
  const server = await loadServer(job);
  if (server.vmid) {
    try {
      await destroyVm(server.vmid);
    } catch (e: any) {
      // VM may never have been created; only swallow "does not exist"
      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
    }
  }
  await db.server.delete({ where: { id: server.id } });
  await syncPortForwards();
}

async function reinstall(job: Job) {
  const server = await loadServer(job);
  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
  if (server.vmid) await destroyVm(server.vmid);
  await provision(job);
}

async function suspend(job: Job, unsuspend: boolean) {
  const server = await loadServer(job);
  if (unsuspend) {
    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
    await syncPortForwards();
    const upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/start`, {});
    await waitForTask(upid);
    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
  } else {
    try {
      const upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/stop`, {});
      await waitForTask(upid);
    } catch { /* may already be stopped */ }
    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
    await syncPortForwards();
  }
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[worker] notify failed", e);
  }
}

async function resize(job: Job) {
  const server = await loadServer(job);
  const payload = (job.payload ?? {}) as { planId?: string };
  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
  if (!newPlan) throw new Error("resize: target plan not found");
  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");

  const wasRunning = server.status === "RUNNING";
  await pve.post(`/nodes/${node}/qemu/${server.vmid}/config`, {
    cores: newPlan.cpuCores,
    memory: newPlan.ramMB,
  });
  if (newPlan.diskGB > server.plan.diskGB) {
    await pve.put(`/nodes/${node}/qemu/${server.vmid}/resize`, {
      disk: "scsi0",
      size: `${newPlan.diskGB}G`,
    });
  }
  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
  // CPU/RAM changes need a power cycle to apply
  if (wasRunning) {
    try {
      const stopUpid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
      await waitForTask(stopUpid, 120_000);
    } catch {
      const stopUpid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/stop`, {});
      await waitForTask(stopUpid);
    }
    const startUpid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/start`, {});
    await waitForTask(startUpid);
  }
  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${newPlan.diskGB} GB disk`,
    `/dashboard/servers/${server.id}`);
}

async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
  const server = await loadServer(job);
  const payload = (job.payload ?? {}) as { name?: string };
  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
  if (!name) throw new Error("snapshot: invalid name");
  let upid: string;
  if (op === "create") {
    upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/snapshot`, { snapname: name });
  } else if (op === "delete") {
    upid = await pve.del(`/nodes/${node}/qemu/${server.vmid}/snapshot/${name}`);
  } else {
    upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
  }
  await waitForTask(upid, 600_000);
  if (op === "rollback") {
    // rollback leaves the VM stopped; bring it back if the server should be running
    const current = await db.server.findUnique({ where: { id: server.id } });
    if (current?.status === "RUNNING") {
      try {
        const startUpid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/start`, {});
        await waitForTask(startUpid);
      } catch { /* may already be running */ }
    }
  }
}

async function passwordReset(job: Job) {
  const server = await loadServer(job);
  if (!server.vmid) throw new Error("password reset: server has no VM yet");
  const password = generatePassword();

  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
  let applied = false;
  try {
    const upid = await pve.post(
      `/nodes/${node}/qemu/${server.vmid}/agent/set-user-password`,
      { username: "root", password }
    );
    // agent endpoints return a UPID on this cluster; wait if so, otherwise it's synchronous.
    if (typeof upid === "string" && upid.startsWith("UPID")) await waitForTask(upid);
    applied = true;
  } catch (e) {
    console.error("[worker] agent set-user-password failed, falling back to cloud-init", e);
  }

  // Fallback: rewrite cloud-init password and reboot so it reapplies.
  if (!applied) {
    await pve.post(`/nodes/${node}/qemu/${server.vmid}/config`, { cipassword: password });
    if (server.status === "RUNNING") {
      const upid = await pve.post(`/nodes/${node}/qemu/${server.vmid}/status/reboot`, {});
      await waitForTask(upid);
    }
  }

  await db.server.update({ where: { id: server.id }, data: { rootPassword: password } });
  await notify(
    server.userId,
    `Root password reset for ${server.hostname}`,
    "Your new root password is available on the server's Overview tab.",
    `/dashboard/servers/${server.id}`
  );
}

async function backupCreate(job: Job) {
  const server = await loadServer(job);
  const upid = await pve.post(`/nodes/${node}/vzdump`, {
    vmid: server.vmid,
    storage: "backup",
    mode: "snapshot",
    compress: "zstd",
  });
  await waitForTask(upid, 3_600_000);
  await notify(server.userId, `Backup completed for ${server.hostname}`, undefined,
    `/dashboard/servers/${server.id}`);
}

const handlers: Record<string, (job: Job) => Promise<void>> = {
  PROVISION: provision,
  START: (j) => powerAction(j, "start"),
  STOP: (j) => powerAction(j, "stop"),
  REBOOT: (j) => powerAction(j, "reboot"),
  DELETE: remove,
  REINSTALL: reinstall,
  SUSPEND: (j) => suspend(j, false),
  UNSUSPEND: (j) => suspend(j, true),
  RESIZE: resize,
  SNAPSHOT_CREATE: (j) => snapshotOp(j, "create"),
  SNAPSHOT_DELETE: (j) => snapshotOp(j, "delete"),
  SNAPSHOT_ROLLBACK: (j) => snapshotOp(j, "rollback"),
  BACKUP_CREATE: backupCreate,
  PASSWORD_RESET: passwordReset,
  SYNC_FORWARDS: async () => syncPortForwards(),
};

async function runJob(job: Job) {
  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
  await db.job.update({
    where: { id: job.id },
    data: { status: "RUNNING", attempts: { increment: 1 } },
  });
  try {
    await handlers[job.type](job);
    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
    console.log(`[worker] job ${job.id} DONE`);
  } catch (e: any) {
    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
    console.error(`[worker] job ${job.id} FAILED: ${error}`);
    const current = await db.job.findUnique({ where: { id: job.id } });
    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
    await db.job.update({
      where: { id: job.id },
      data: { status: retriable ? "QUEUED" : "FAILED", error },
    });
    if (!retriable && job.serverId) {
      const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
      if (stillExists) {
        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
      }
    }
  }
}

async function main() {
  console.log("[worker] Nxeon provisioning worker starting");
  await syncPortForwards();
  console.log("[worker] port forwards synced");

  let lastSweep = 0;
  for (;;) {
    if (Date.now() - lastSweep > 10 * 60_000) {
      lastSweep = Date.now();
      try {
        await billingSweep();
      } catch (e) {
        console.error("[billing] sweep error", e);
      }
    }
    try {
      const job = await db.job.findFirst({
        where: { status: "QUEUED" },
        orderBy: { createdAt: "asc" },
      });
      if (job) {
        await runJob(job);
      } else {
        await new Promise((r) => setTimeout(r, POLL_MS));
      }
    } catch (e) {
      console.error("[worker] loop error", e);
      await new Promise((r) => setTimeout(r, POLL_MS));
    }
  }
}

main();

import { db } from "../lib/db";
import { registrarConfigured, renewDomain } from "../lib/registrar";
import { vpsTerm, vpsTermPriceCents, domainTerm, domainTermPriceCents, addMonths } from "../lib/billing-terms";

const GRACE_DAYS = 3;
const RENEW_DAYS = 30;
const DOMAIN_RENEW_WINDOW_DAYS = 7;

/**
 * Subscription sweep, run periodically by the worker:
 *  - expired + autoRenew + sufficient balance  -> charge wallet, extend 30 days
 *  - expired beyond grace (or autoRenew off)   -> queue SUSPEND with unpaid note
 * Free servers (isFree) are never touched.
 */
export async function billingSweep() {
  const now = new Date();

  // Renewal warnings: notify once when a paid server is within 3 days of expiry
  const soon = new Date(now.getTime() + 3 * 86400_000);
  const upcoming = await db.server.findMany({
    where: {
      isFree: false,
      expiresAt: { gt: now, lt: soon },
      status: { in: ["RUNNING", "STOPPED"] },
    },
    include: { plan: true, user: true },
  });
  for (const server of upcoming) {
    if (server.autoRenew && server.user.balanceCents >= vpsTermPriceCents(server.plan.priceCents, server.termMonths)) continue;
    const already = await db.notification.findFirst({
      where: {
        userId: server.userId,
        title: { contains: server.hostname },
        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
        AND: { title: { contains: "renews soon" } },
      },
    });
    if (!already) {
      await db.notification.create({
        data: {
          userId: server.userId,
          title: `${server.hostname} renews soon — action needed`,
          body: server.autoRenew
            ? `Renewal is $${(server.plan.priceCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
          href: `/dashboard/servers/${server.id}`,
        },
      });
    }
  }
  const due = await db.server.findMany({
    where: {
      isFree: false,
      expiresAt: { lt: now },
      status: { in: ["RUNNING", "STOPPED"] },
    },
    include: { plan: true, user: true },
  });

  for (const server of due) {
    const graceEnd = new Date(server.expiresAt!.getTime() + GRACE_DAYS * 86400_000);
    const renewTerm = vpsTerm(server.termMonths);
    const renewCents = vpsTermPriceCents(server.plan.priceCents, renewTerm.months);

    if (server.autoRenew && server.user.balanceCents >= renewCents) {
      const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
      const newExpiry = addMonths(base, renewTerm.months);
      await db.$transaction([
        db.user.update({
          where: { id: server.userId },
          data: { balanceCents: { decrement: renewCents } },
        }),
        db.walletTransaction.create({
          data: {
            userId: server.userId,
            amountCents: -renewCents,
            description: `Renewal: ${server.plan.name} VPS (${server.hostname}) — ${renewTerm.label}`,
          },
        }),
        db.server.update({
          where: { id: server.id },
          data: { expiresAt: newExpiry },
        }),
        db.auditLog.create({
          data: { userId: server.userId, action: "billing.renewed", detail: server.id },
        }),
      ]);
      console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
    } else if (now > graceEnd) {
      const pending = await db.job.count({
        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
      });
      if (pending === 0) {
        await db.server.update({
          where: { id: server.id },
          data: { suspendedNote: "unpaid — renew from your billing page to restore access" },
        });
        await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
        await db.auditLog.create({
          data: { userId: server.userId, action: "billing.suspended_unpaid", detail: server.id },
        });
        await db.notification.create({
          data: {
            userId: server.userId,
            title: `${server.hostname} suspended — payment overdue`,
            body: "Pay from the server page to restore access instantly.",
            href: `/dashboard/servers/${server.id}`,
          },
        });
        console.log(`[billing] suspending unpaid ${server.hostname}`);
      }
    }
  }

  await domainAutoRenewSweep(now);
}

/**
 * Auto-renew domains expiring within 7 days when the owner opted in and has
 * the funds. Charges the wallet, extends expiry +365d and notifies the owner.
 * Failures (registrar error, misconfig) notify the owner to renew manually and
 * never charge the wallet.
 */
async function domainAutoRenewSweep(now: Date) {
  if (!registrarConfigured()) return; // registrar not configured — skip silently

  const cutoff = new Date(now.getTime() + DOMAIN_RENEW_WINDOW_DAYS * 86400_000);
  const domains = await db.domain.findMany({
    where: {
      autoRenew: true,
      status: "ACTIVE",
      expiresAt: { not: null, lt: cutoff },
    },
    include: { user: true },
  });

  for (const domain of domains) {
    if (!domain.expiresAt) continue;
    const dTerm = domainTerm(domain.termYears);
    const dRenewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
    if (domain.user.balanceCents < dRenewCents) {
      const already = await db.notification.findFirst({
        where: {
          userId: domain.userId,
          title: { contains: domain.name },
          AND: { title: { contains: "auto-renew failed" } },
          createdAt: { gt: new Date(now.getTime() - 3 * 86400_000) },
        },
      });
      if (!already) {
        await db.notification.create({
          data: {
            userId: domain.userId,
            title: `${domain.name} auto-renew failed — top up to renew`,
            body: `Renewal is $${(dRenewCents / 100).toFixed(2)} (${dTerm.label}) but your balance is $${(domain.user.balanceCents / 100).toFixed(2)}. Top up and renew manually before ${domain.expiresAt.toISOString().slice(0, 10)}.`,
            href: `/dashboard/domains`,
          },
        });
      }
      continue;
    }

    try {
      await renewDomain(domain.name, dTerm.years, dRenewCents);
    } catch (e) {
      console.error(`[billing] domain auto-renew failed for ${domain.name}`, e);
      await db.notification.create({
        data: {
          userId: domain.userId,
          title: `${domain.name} auto-renew failed — please renew manually`,
          body: `We couldn't renew ${domain.name} automatically: ${String((e as any)?.message ?? e).slice(0, 200)}. Renew it manually from your domains page.`,
          href: `/dashboard/domains`,
        },
      });
      continue;
    }

    const newExpiry = new Date(domain.expiresAt.getTime() + dTerm.years * 365 * 86400_000);
    await db.$transaction([
      db.user.update({
        where: { id: domain.userId },
        data: { balanceCents: { decrement: dRenewCents } },
      }),
      db.walletTransaction.create({
        data: {
          userId: domain.userId,
          amountCents: -dRenewCents,
          description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
        },
      }),
      db.domain.update({ where: { id: domain.id }, data: { expiresAt: newExpiry } }),
      db.auditLog.create({
        data: { userId: domain.userId, action: "domain.auto_renewed", detail: domain.name },
      }),
    ]);
    await db.notification.create({
      data: {
        userId: domain.userId,
        title: `${domain.name} renewed automatically`,
        body: `Charged $${(domain.priceCents / 100).toFixed(2)}. New expiry: ${newExpiry.toISOString().slice(0, 10)}.`,
        href: `/dashboard/domains`,
      },
    });
    console.log(`[billing] auto-renewed domain ${domain.name} until ${newExpiry.toISOString()}`);
  }
}

